begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
grant analysis_writer to postgres with set true;
grant usage on schema extensions to analysis_writer;
insert into auth.users(id,is_anonymous) values('eb100000-0000-4000-8000-000000000001',true),('eb100000-0000-4000-8000-000000000002',false),('eb100000-0000-4000-8000-000000000003',false);
insert into public.organizations(id,name) values('eb200000-0000-4000-8000-000000000001','Complete catalog A'),('eb200000-0000-4000-8000-000000000002','Complete catalog B');
insert into public.stores(id,org_id,name) values('eb300000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','A'),('eb300000-0000-4000-8000-000000000002','eb200000-0000-4000-8000-000000000002','B');
insert into public.memberships(org_id,user_id,role) values('eb200000-0000-4000-8000-000000000001','eb100000-0000-4000-8000-000000000002','owner'),('eb200000-0000-4000-8000-000000000002','eb100000-0000-4000-8000-000000000003','owner');
insert into public.devices(id,org_id,store_id,auth_user_id,label) values('eb400000-0000-4000-8000-000000000001','eb200000-0000-4000-8000-000000000001','eb300000-0000-4000-8000-000000000001','eb100000-0000-4000-8000-000000000001','A');
create temporary table catalog_context(key text primary key,value text);
grant all on catalog_context to authenticated,anon,analysis_writer;
create function pg_temp.val(k text) returns uuid language sql as $$ select value::uuid from catalog_context where key=k $$;
-- Fixture construction uses the normalized tables; all publication/read/save actions below run as actual API roles.
create function pg_temp.variant(cat text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_brand uuid;v_category uuid;v_product uuid;v_variant uuid;v_form uuid;v_ing uuid;
begin
 insert into public.brands(org_id,name) values('eb200000-0000-4000-8000-000000000001','Fixture') on conflict(org_id,name) do update set name=excluded.name returning id into v_brand;
 insert into public.categories(org_id,name) values('eb200000-0000-4000-8000-000000000001',cat) returning id into v_category;
 insert into public.products(org_id,brand_id,category_id,name) values('eb200000-0000-4000-8000-000000000001',v_brand,v_category,cat||' item') returning id into v_product;
 insert into public.product_variants(org_id,product_id,sku) values('eb200000-0000-4000-8000-000000000001',v_product,cat||'-1') returning id into v_variant;
 insert into public.formulation_versions(org_id,product_id,version,complete) values('eb200000-0000-4000-8000-000000000001',v_product,1,true) returning id into v_form;
 insert into public.ingredients(inci_name) values('Niacinamide') on conflict(inci_name) do nothing;select id into v_ing from public.ingredients where inci_name='Niacinamide';
 insert into public.formulation_ingredients values('eb200000-0000-4000-8000-000000000001',v_form,v_ing,1);
 update public.formulation_versions set status='published',published_at=now() where id=v_form;
 insert into public.variant_formulations values('eb200000-0000-4000-8000-000000000001',v_variant,v_product,v_form);
 insert into public.store_listings values('eb200000-0000-4000-8000-000000000001','eb300000-0000-4000-8000-000000000001',v_variant,2500,'USD',5,true);
 return v_variant;
end $$;
insert into catalog_context values('foundation',pg_temp.variant('foundation')),('blush',pg_temp.variant('blush')),('lip',pg_temp.variant('lip_color')),('skin',pg_temp.variant('serum'));
select is((select count(*)::integer from pg_tables where schemaname='public' and tablename in ('cosmetic_shade_versions','cosmetic_color_details','cosmetic_base_details','cosmetic_variant_shades') and rowsecurity),4,'Four normalized shade relations have RLS');
select ok(not has_table_privilege('authenticated','public.cosmetic_shade_versions','SELECT,INSERT,UPDATE,DELETE'),'No direct staff/device shade mutations');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eb100000-0000-4000-8000-000000000002","is_anonymous":false}',true);
insert into catalog_context values('foundationShade',public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('foundation'),'{"category":"foundation","shadeName":"M cool","undertone":"cool","finish":"natural","swatchHex":"#BE927D","reviewed":true,"depth":"medium","coverage":"medium"}')::text);
select throws_ok($$select public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('foundation'),'{"category":"blush","shadeName":"Wrong","undertone":"cool","finish":"satin","swatchHex":"#BE927D","reviewed":true,"hueFamily":"rose","intensity":"soft"}')$$,'22023',null,'Category-specific publication cannot cross foundation into blush');
select throws_ok($$select public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('foundation'),'{"category":"foundation","shadeName":"Wrong","undertone":"cool","finish":"natural","swatchHex":"#BE927D","reviewed":false,"depth":"medium","coverage":"medium"}')$$,'22023',null,'Unreviewed shade cannot publish');
select public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('blush'),'{"category":"blush","shadeName":"Soft rose","undertone":"cool","finish":"satin","swatchHex":"#C38DAB","reviewed":true,"hueFamily":"rose","intensity":"soft"}');
insert into catalog_context values('legacyLip',public.publish_lip_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('lip'),'{"shadeName":"Rose lip","undertone":"cool","finish":"satin","swatchHex":"#C38DAB","reviewed":true,"hueFamily":"rose","intensity":"soft"}')::text);
select is(jsonb_array_length(public.read_store_cosmetic_shades('eb300000-0000-4000-8000-000000000001')),3,'Reviewed common read includes all category-specific shades and legacy lip');
select set_config('request.jwt.claims','{"sub":"eb100000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select throws_ok($$select public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('foundation'),'{"category":"foundation","shadeName":"M cool","undertone":"cool","finish":"natural","swatchHex":"#BE927D","reviewed":true,"depth":"medium","coverage":"medium"}')$$,'42501',null,'Other tenant owner cannot publish shade');
select throws_ok($$select public.read_store_cosmetic_shades('eb300000-0000-4000-8000-000000000001')$$,'42501',null,'Other tenant owner cannot inspect shade catalog');
reset role;
select is((select id::text from public.cosmetic_shade_versions where id=pg_temp.val('legacyLip')),(select value from catalog_context where key='legacyLip'),'Legacy immutable lip version retains its ID in common schema');
set local role analysis_writer;
select throws_ok($$select public.persist_recommendations('eb900000-0000-4000-8000-000000000001','eb900000-0000-4000-8000-000000000002','eb900000-0000-4000-8000-000000000003',jsonb_build_array(jsonb_build_object('variant_id',pg_temp.val('foundation'))))$$,'22023',null,'Preserved skincare writer rejects all cosmetic categories');
reset role;
select throws_ok($$insert into public.cosmetic_color_details values('eb200000-0000-4000-8000-000000000001',pg_temp.val('foundationShade'),'blush','rose','soft')$$,'23503',null,'Composite subtype FK prevents base shade acquiring color subtype');
select throws_ok($$update public.cosmetic_base_details set depth='light' where shade_version_id=pg_temp.val('foundationShade')$$,'23514',null,'Published base metadata immutable');
insert into public.recommendation_policy_versions(org_id,version) values('eb200000-0000-4000-8000-000000000001',1);
insert into public.concern_ingredient_rules select 'eb200000-0000-4000-8000-000000000001',p.id,c.id,i.id,2 from public.recommendation_policy_versions p cross join public.concerns c cross join public.ingredients i where p.org_id='eb200000-0000-4000-8000-000000000001' and c.slug='texture' and i.inci_name='Niacinamide';
update public.recommendation_policy_versions set status='published',published_at=now() where org_id='eb200000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eb100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
insert into catalog_context values('session',public.start_kiosk_session()::text);
select public.kiosk_set_beauty_guest_context(pg_temp.val('session'),'25-34','es',false);
select public.record_consent(pg_temp.val('session'),'2026-10-openai-v1',true);
select public.confirm_complete_beauty_preferences(pg_temp.val('session'),'{"paletteId":"cool_soft","faceShape":"oval","hairLength":"any","mood":"fresh","finish":"any"}');
select throws_ok($$select public.create_complete_beauty_guide(pg_temp.val('session'),repeat('b',64),'2026-10-complete-save-v1',array[pg_temp.val('foundation')])$$,'22023',null,'Unknown base context cannot save a claimed foundation match');
select public.kiosk_set_complete_base_choice(pg_temp.val('session'),'medium','cool','match');
select throws_ok($$select public.create_complete_beauty_guide(pg_temp.val('session'),repeat('b',64),'2026-10-complete-save-v1',array[pg_temp.val('skin')])$$,'22023',null,'No goal cannot save an arbitrary skincare product');
select public.kiosk_set_complete_skin_profile(pg_temp.val('session'),'unsure',array['texture'],array[]::text[]);
select lives_ok($$select public.create_complete_beauty_guide(pg_temp.val('session'),repeat('b',64),'2026-10-complete-save-v1',array[pg_temp.val('skin'),pg_temp.val('foundation'),pg_temp.val('blush'),pg_temp.val('lip')])$$,'Photo-free confirmed choices save independently validated skincare and cosmetics');
select public.finish_kiosk_beauty_complete(pg_temp.val('session'),null);
reset role;
select is((select count(*)::integer from public.analyses where org_id='eb200000-0000-4000-8000-000000000001'),0,'Manual save never manufactures analysis or provider attempt');
set local role anon;
select is(jsonb_array_length(public.read_complete_beauty_guide(repeat('b',64))->'products'),4,'Public guide has skincare, foundation, blush and lip references');
select is(public.read_complete_beauty_guide(repeat('b',64))->'products'->0->>'available','true','Original published formula currently available');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"eb100000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select public.publish_cosmetic_shade('eb300000-0000-4000-8000-000000000001',pg_temp.val('foundation'),'{"category":"foundation","shadeName":"New M cool","undertone":"cool","finish":"natural","swatchHex":"#BE927D","reviewed":true,"depth":"medium","coverage":"medium"}');
reset role;
set local role anon;
select is(public.read_complete_beauty_guide(repeat('b',64))->'products'->1->>'available','false','Changed shade marks original saved recommendation unavailable');
select is(public.read_complete_beauty_guide(repeat('b',64))->'products'->1->>'shadeName','M cool','Saved guide never silently substitutes new shade');
reset role;
update public.complete_beauty_saved_guides set expires_at=now()-interval '1 second' where token_hash=repeat('b',64);
set local role anon;
select is(public.read_complete_beauty_guide(repeat('b',64)),null::jsonb,'Expired guide unavailable before cleanup job');
reset role;
delete from public.beauty_saved_guides where expires_at<=now();
select is((select count(*)::integer from public.complete_beauty_saved_guides where token_hash=repeat('b',64)),0,'Minute legacy cleanup also removes new expired capabilities');
select * from finish();rollback;
